export class CircuitBreaker {
  private currentState: CircuitState;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private consecutiveFailures: number;
  private nextAttemptTimestamp: number;

  constructor(options?: CircuitBreakerOptions) {
    const threshold = options?.failureThreshold;
    const timeout = options?.resetTimeoutMs;

    this.failureThreshold = typeof threshold === 'number' && threshold > 0 ? threshold : 5;
    this.resetTimeoutMs = typeof timeout === 'number' && timeout > 0 ? timeout : 10000;
    this.currentState = 'CLOSED';
    this.consecutiveFailures = 0;
    this.nextAttemptTimestamp = 0;
  }

  public get state(): CircuitState {
    return this.getState();
  }

  public getState(): CircuitState {
    if (this.currentState === 'OPEN') {
      const now = Date.now();
      if (now >= this.nextAttemptTimestamp) {
        this.currentState = 'HALF_OPEN';
      }
    }
    return this.currentState;
  }

  public recordSuccess(): void {
    this.consecutiveFailures = 0;
    this.currentState = 'CLOSED';
  }

  public recordFailure(): void {
    this.consecutiveFailures += 1;
    if (this.currentState === 'HALF_OPEN' || this.consecutiveFailures >= this.failureThreshold) {
      this.currentState = 'OPEN';
      this.nextAttemptTimestamp = Date.now() + this.resetTimeoutMs;
    }
  }

  public async execute<T>(action: () => Promise<T>): Promise<T> {
    const currentState = this.getState();

    if (currentState === 'OPEN') {
      throw new CircuitBreakerOpenError();
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error: unknown) {
      this.recordFailure();
      throw error;
    }
  }
}

