export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  public async get<T>(url: string, options?: RequestOptions): Promise<T> {
    return this.circuitBreaker.execute<T>(async (): Promise<T> => {
      const abortController = new AbortController();
      let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

      const timeoutMs = options?.timeoutMs;
      if (typeof timeoutMs === 'number' && timeoutMs > 0) {
        timeoutHandle = setTimeout(() => {
          abortController.abort();
        }, timeoutMs);
      }

      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: options?.headers,
          signal: abortController.signal,
        });

        if (!response.ok) {
          const statusText = response.statusText ? ` ${response.statusText}` : '';
          throw new ApiError(`Request failed with status code ${response.status}${statusText}`, response.status);
        }

        const data: unknown = await response.json();
        return data as T;
      } catch (error: unknown) {
        if (error instanceof ApiError) {
          throw error;
        }

        if (error instanceof Error && error.name === 'AbortError') {
          throw new Error(`Request timed out after ${timeoutMs}ms`);
        }

        if (error instanceof Error) {
          throw error;
        }

        throw new Error(String(error));
      } finally {
        if (timeoutHandle !== undefined) {
          clearTimeout(timeoutHandle);
        }
      }
    });
  }
}
